		it("should cache the result of isGlobalReference for the same node", () => {
			const code = "Math; Math;";
			let firstNode, secondNode, sourceCodeInstance;

			const config = {
				plugins: {
					test: {
						rules: {
							checker: {
								create(context) {
									const sourceCode = context.sourceCode;
									sourceCodeInstance = sourceCode;
									return {
										Identifier(node) {
											if (!firstNode) {
												firstNode = node;
											} else if (!secondNode) {
												secondNode = node;
