					phase: 1,
				},
				{
					type: "Identifier",
					phase: 1,
				},
				{
					type: "Identifier",
					phase: 2,
				},
				{
					type: "Literal",
					phase: 1,
				},
				{
					type: "Literal",
					phase: 2,
				},
				{
					type: "VariableDeclarator",
					phase: 2,
				},
				{
					type: "VariableDeclaration",
					phase: 2,
				},
