		it("should shadow the same name variable by the iteration variable.", () => {
			const { node, scope } = getScope(
				"let x; for (let x of x) {}",
				"ForOfStatement",
				2015,
			);

			assert.strictEqual(scope.type, "for");
			assert.strictEqual(scope.upper.type, "global");
