			});
		});

		describe("when a valid cache file already exists", () => {
			beforeEach(() => {
				const child = runESLint(ARGS_WITH_CACHE);

				return assertExitCode(child, 0).then(() => {
					assert.isTrue(
						fs.existsSync(CACHE_PATH),
						"Cache file should exist at the given location",
