			const child = runESLint(["--stdin", "--no-config-lookup"]);

			child.stdin.write("var foo = bar;\n");
			child.stdin.end();
			return assertExitCode(child, 0);
		});

		it("has exit code 0 if no linting errors are reported", () => {
			const child = runESLint(
